# Generated by build.py from recipe.yml for recipe smtp-serve-a-mail-domain. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:secret', '--mailbox', 'bob@example.com:hunter2', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
